import React, { useState, useEffect } from 'react';
import { useAuth } from '../context/AuthContext';
import './Appointments.css';
import {
  getAppointments,
  getPatients,
  getProfessionals,
  createAppointment,
  deleteAppointment,
  registerAppointmentGpsEvent
} from '../services/api';

const weekdayLabels = ['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'];

function formatDateKey(date) {
  const d = new Date(date);
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, '0');
  const dd = String(d.getDate()).padStart(2, '0');
  return `${yyyy}-${mm}-${dd}`;
}

function isSameDay(a, b) {
  return (
    a.getFullYear() === b.getFullYear() &&
    a.getMonth() === b.getMonth() &&
    a.getDate() === b.getDate()
  );
}

function getWeekStart(date) {
  const copy = new Date(date);
  const day = copy.getDay();
  const diff = day === 0 ? -6 : 1 - day;
  copy.setDate(copy.getDate() + diff);
  return copy;
}

export default function Calendar() {
  const [appointments, setAppointments] = useState([]);
  const [patients, setPatients] = useState([]);
  const [professionals, setProfessionals] = useState([]);
  const [categoryFilter, setCategoryFilter] = useState('medico');
  const [form, setForm] = useState({ patientId: '', professionalId: '', appointmentDate: '', appointmentTime: '', reason: '' });
  const [showForm, setShowForm] = useState(false);

  const professionalCategories = [
    { value: 'medico', label: 'Médico' },
    { value: 'kinesiologo', label: 'Kinesiólogo' },
    { value: 'enfermera', label: 'Enfermería' },
    { value: 'quiropractico', label: 'Quiropráctico' }
  ];
  const [view, setView] = useState('month');
  const [currentDate, setCurrentDate] = useState(new Date());
  const { user } = useAuth();

  const [selectedAppointment, setSelectedAppointment] = useState(null);
  const [modalOpen, setModalOpen] = useState(false);
  const [modalMessage, setModalMessage] = useState('');
  const [modalLoading, setModalLoading] = useState(false);

  useEffect(() => {
    fetchAppointments();
    fetchPatients();
    fetchProfessionals();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const fetchAppointments = async () => {
    try {
      const res = await getAppointments();
      setAppointments(res.data || []);
    } catch (err) {
      console.error('Error fetching appointments', err);
    }
  };

  const fetchPatients = async () => {
    try {
      const res = await getPatients();
      setPatients(res.data || []);
    } catch (err) {
      console.error('Error fetching patients', err);
    }
  };

  const fetchProfessionals = async () => {
    try {
      const res = await getProfessionals();
      setProfessionals(res.data || []);
    } catch (err) {
      console.error('Error fetching professionals', err);
    }
  };

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await createAppointment(form);
      setForm({ patientId: '', appointmentDate: '', appointmentTime: '', reason: '', specialty: '', doctorName: '' });
      setShowForm(false);
      fetchAppointments();
    } catch (err) {
      console.error('Error creating appointment', err);
    }
  };

  const appointmentsByDate = appointments.reduce((acc, appointment) => {
    const key = appointment.appointmentDate;
    if (!acc[key]) acc[key] = [];
    acc[key].push(appointment);
    return acc;
  }, {});

  const handleChangeView = (nextView) => {
    setView(nextView);
  };

  const handlePrevious = () => {
    const next = new Date(currentDate);
    if (view === 'month') next.setMonth(next.getMonth() - 1);
    else if (view === 'week') next.setDate(next.getDate() - 7);
    else next.setDate(next.getDate() - 1);
    setCurrentDate(next);
  };

  const handleNext = () => {
    const next = new Date(currentDate);
    if (view === 'month') next.setMonth(next.getMonth() + 1);
    else if (view === 'week') next.setDate(next.getDate() + 7);
    else next.setDate(next.getDate() + 1);
    setCurrentDate(next);
  };

  const handleToday = () => setCurrentDate(new Date());

  const openModal = (appointment) => {
    setSelectedAppointment(appointment);
    setModalMessage('');
    setModalOpen(true);
  };

  const closeModal = () => {
    setModalOpen(false);
    setSelectedAppointment(null);
  };

  const handleRegisterGps = (id, eventType = 'arrival') => {
    if (!navigator.geolocation) {
      setModalMessage('Geolocalización no está disponible en este navegador');
      return;
    }

    setModalMessage('Obteniendo ubicación...');
    setModalLoading(true);

    navigator.geolocation.getCurrentPosition(
      async ({ coords }) => {
        try {
          await registerAppointmentGpsEvent(id, {
            latitude: coords.latitude,
            longitude: coords.longitude,
            eventType,
            timestamp: new Date().toISOString(),
            notes: `Registro GPS ${eventType} desde calendario`
          });
          setModalMessage(`Evento GPS ${eventType} registrado: ${coords.latitude.toFixed(6)}, ${coords.longitude.toFixed(6)}`);
          fetchAppointments();
        } catch (err) {
          console.error('Error registering GPS', err);
          setModalMessage('Error al registrar la ubicación GPS');
        } finally {
          setModalLoading(false);
        }
      },
      (error) => {
        console.error('Geolocation error:', error);
        if (error.code === 1) setModalMessage('Permiso denegado para geolocalización');
        else if (error.code === 2) setModalMessage('No se pudo obtener la ubicación');
        else setModalMessage('Error al obtener la ubicación GPS');
        setModalLoading(false);
      },
      { enableHighAccuracy: true, timeout: 15000, maximumAge: 0 }
    );
  };

  const handleDeleteAppointment = async (id) => {
    if (!window.confirm('¿Eliminar cita?')) return;
    try {
      await deleteAppointment(id);
      setModalOpen(false);
      fetchAppointments();
    } catch (err) {
      console.error('Error deleting appointment', err);
      setModalMessage('Error al eliminar la cita');
    }
  };

  const renderMonthGrid = () => {
    const year = currentDate.getFullYear();
    const month = currentDate.getMonth();
    const firstDayOfMonth = new Date(year, month, 1);
    const startOffset = (firstDayOfMonth.getDay() + 6) % 7;
    const gridStartDate = new Date(firstDayOfMonth);
    gridStartDate.setDate(gridStartDate.getDate() - startOffset);
    const cells = Array.from({ length: 42 }).map((_, idx) => {
      const date = new Date(gridStartDate);
      date.setDate(gridStartDate.getDate() + idx);
      const key = formatDateKey(date);
      const items = appointmentsByDate[key] || [];
      const isCurrentMonth = date.getMonth() === month;
      const isToday = isSameDay(date, new Date());
      return (
        <div key={key} className={`calendar-cell ${isCurrentMonth ? '' : 'outside'} ${isToday ? 'today' : ''}`}>
          <div className="calendar-cell-header">
            <span className={isToday ? 'current' : ''}>{date.getDate()}</span>
            {items.length > 0 && <small>{items.length} cita{items.length > 1 ? 's' : ''}</small>}
          </div>
          <div className="calendar-events">
            {items.slice(0, 3).map((item) => (
              <div key={item.id} className="calendar-event" onClick={() => openModal(item)}>
                {item.patientName} {item.patientLastName}
              </div>
            ))}
            {items.length > 2 && <div className="calendar-event more">+{items.length - 2} más</div>}
          </div>
        </div>
      );
    });

    return (
      <div className="calendar-grid">
        <div className="calendar-weekdays">
          {weekdayLabels.map((label) => (
            <div key={label} className="calendar-weekday">{label}</div>
          ))}
        </div>
        {cells}
      </div>
    );
  };

  const renderWeekView = () => {
    const start = getWeekStart(currentDate);
    const days = Array.from({ length: 7 }).map((_, index) => {
      const date = new Date(start);
      date.setDate(start.getDate() + index);
      const key = formatDateKey(date);
      const items = appointmentsByDate[key] || [];
      return (
        <div key={key} className="calendar-list-item">
          <div>
            <strong>{weekdayLabels[index]} {date.getDate()}</strong>
            <div>{date.toLocaleDateString('es-ES', { month: 'short' })}</div>
          </div>
          <div>
            {items.length > 0 ? (
              <div>
                {items.slice(0,3).map(i => (
                  <div key={i.id} style={{cursor:'pointer'}} onClick={() => openModal(i)}>{i.patientName} {i.patientLastName}</div>
                ))}
              </div>
            ) : 'Sin citas'}
          </div>
        </div>
      );
    });

    return (
      <div className="calendar-list">
        <h3>Semana del {formatDateKey(start)}</h3>
        {days}
      </div>
    );
  };

  const renderDayView = () => {
    const date = new Date(currentDate);
    const key = formatDateKey(date);
    const items = appointmentsByDate[key] || [];

    return (
      <div className="calendar-list">
        <h3>{date.toLocaleDateString('es-ES', { weekday: 'long', year: 'numeric', month: 'long', day: 'numeric' })}</h3>
        {items.length === 0 ? (
          <div className="calendar-empty">No hay citas para este día.</div>
        ) : (
          items.map((item) => (
            <div key={item.id} className="calendar-list-item" onClick={() => openModal(item)} style={{cursor:'pointer'}}>
              <div>
                <strong>{item.patientName} {item.patientLastName}</strong>
                <div>{item.reason}</div>
              </div>
              <div>{item.appointmentTime}</div>
            </div>
          ))
        )}
      </div>
    );
  };

  return (
    <div className="page appointments-page">
      <div className="calendar-header">
        <div className="calendar-title">
          <span className="badge">📅</span>
          <h2>Calendario</h2>
        </div>
        <p className="calendar-description">Controla tus citas, alterna entre mes, semana o día y revisa tus pacientes agendados.</p>
      </div>

      <div className="calendar-actions-row">
        <div className="calendar-controls">
          <div className="calendar-nav">
            <button onClick={handlePrevious}>‹</button>
            <button onClick={handleNext}>›</button>
            <button className="today-button" onClick={handleToday}>Hoy</button>
          </div>

          <div className="calendar-title-text">{currentDate.toLocaleDateString('es-ES', { month: 'long', year: 'numeric' })}</div>

          <div className="calendar-view">
            <button className={view === 'month' ? 'active' : ''} onClick={() => handleChangeView('month')}>Mes</button>
            <button className={view === 'week' ? 'active' : ''} onClick={() => handleChangeView('week')}>Semana</button>
            <button className={view === 'day' ? 'active' : ''} onClick={() => handleChangeView('day')}>Día</button>
          </div>
        </div>

        {user?.role === 'admin' && (
          <button onClick={() => setShowForm(!showForm)} className="btn-primary">{showForm ? 'Cancelar' : '+ Nueva Cita'}</button>
        )}
      </div>

      <div className="calendar-panel">
        <div className="calendar-card">
          {view === 'month' && renderMonthGrid()}
          {view === 'week' && renderWeekView()}
          {view === 'day' && renderDayView()}
        </div>
      </div>

      {showForm && user?.role === 'admin' && (
        <form onSubmit={handleSubmit} className="form-container" style={{ marginTop: '20px' }}>
          <select value={form.patientId} onChange={(e) => setForm({ ...form, patientId: e.target.value })} required>
            <option value="">Selecciona paciente</option>
            {patients.map((p) => (
              <option key={p.id} value={p.id}>{p.firstName} {p.lastName}</option>
            ))}
          </select>
          <input type="date" value={form.appointmentDate} onChange={(e) => setForm({ ...form, appointmentDate: e.target.value })} required />
          <input type="time" value={form.appointmentTime} onChange={(e) => setForm({ ...form, appointmentTime: e.target.value })} required />
          <input type="text" placeholder="Razón" value={form.reason} onChange={(e) => setForm({ ...form, reason: e.target.value })} required />
          <input type="text" placeholder="Especialidad" value={form.specialty} onChange={(e) => setForm({ ...form, specialty: e.target.value })} />
          <input type="text" placeholder="Doctor" value={form.doctorName} onChange={(e) => setForm({ ...form, doctorName: e.target.value })} />
          <button type="submit" className="btn-success">Crear</button>
        </form>
      )}

      {modalOpen && selectedAppointment && (
        <div className="modal-overlay" onClick={closeModal}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <div className="modal-header">
              <h3>Detalle de cita</h3>
              <button className="modal-close" onClick={closeModal}>×</button>
            </div>
            <div style={{ padding: '18px' }}>
              <p><strong>Paciente:</strong> {selectedAppointment.patientName} {selectedAppointment.patientLastName}</p>
              <p><strong>Fecha:</strong> {formatDateKey(new Date(selectedAppointment.appointmentDate))} {selectedAppointment.appointmentTime}</p>
              <p><strong>Profesional:</strong> {selectedAppointment.professionalFirstName ? `${selectedAppointment.professionalFirstName} ${selectedAppointment.professionalLastName}` : 'Sin asignar'}</p>
              <p><strong>Motivo:</strong> {selectedAppointment.reason || '-'}</p>

              {selectedAppointment.arrivalLatitude && selectedAppointment.arrivalLongitude && (
                <p><strong>Llegada registrada:</strong> {Number(selectedAppointment.arrivalLatitude).toFixed(6)}, {Number(selectedAppointment.arrivalLongitude).toFixed(6)}</p>
              )}
              {selectedAppointment.startLatitude && selectedAppointment.startLongitude && (
                <p><strong>Inicio registrado:</strong> {Number(selectedAppointment.startLatitude).toFixed(6)}, {Number(selectedAppointment.startLongitude).toFixed(6)}</p>
              )}

              {modalMessage && <div className="status-message info" style={{ marginTop: 8 }}>{modalMessage}</div>}

              <div style={{ display: 'flex', gap: 10, marginTop: 12 }}>
                {user?.role === 'medico' && (
                  <>
                    <button type="button" className="btn-secondary" onClick={() => handleRegisterGps(selectedAppointment.id, 'arrival')} disabled={modalLoading}>{modalLoading ? 'Registrando...' : 'Registrar llegada GPS'}</button>
                    <button type="button" className="btn-secondary" onClick={() => handleRegisterGps(selectedAppointment.id, 'start')} disabled={modalLoading}>{modalLoading ? 'Registrando...' : 'Registrar inicio GPS'}</button>
                  </>
                )}

                {user?.role === 'admin' && (
                  <>
                    <button type="button" className="btn-primary" onClick={() => { closeModal(); /* open edit */ }}>Editar</button>
                    <button type="button" className="btn-danger" onClick={() => handleDeleteAppointment(selectedAppointment.id)}>Eliminar</button>
                  </>
                )}
              </div>
            </div>
          </div>
        </div>
      )}
    </div>
  );
}
